let _RCTX = {};
const _nodeFetch = (typeof fetch === 'function') ? fetch : null;
const _n8nHttpReq = (typeof this !== 'undefined' && this && this.helpers && typeof this.helpers.httpRequest === 'function')
  ? this.helpers.httpRequest.bind(this.helpers)
  : null;
async function safeFetch(urlStr, opts = {}) {
  if (_nodeFetch) return _nodeFetch(urlStr, opts);
  if (_n8nHttpReq) {
    try {
      const r = await _n8nHttpReq({
        method: opts.method || 'GET',
        url: urlStr,
        headers: opts.headers || {},
        body: opts.body,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true,
        timeout: Number(opts.timeoutMs || 10000)
      });
      const st = Number(r?.statusCode || r?.status || 200);
      const rawBody = (r && r.body !== undefined) ? r.body : r;
      const textStr = typeof rawBody === 'string' ? rawBody : JSON.stringify(rawBody ?? {});
      return {
        ok: st >= 200 && st < 300,
        status: st,
        text: async () => textStr,
        json: async () => (typeof rawBody === 'object' && rawBody !== null ? rawBody : JSON.parse(textStr || '{}')),
        arrayBuffer: async () => Buffer.from(textStr, 'utf8')
      };
    } catch (_) {}
  }
  try {
    const https = require('https');
    const http = require('http');
    const u = new URL(urlStr);
    const mod = u.protocol === 'http:' ? http : https;
    return await new Promise((resolve, reject) => {
      const req = mod.request({
        hostname: u.hostname,
        port: u.port || (u.protocol === 'http:' ? 80 : 443),
        path: u.pathname + u.search,
        method: opts.method || 'GET',
        headers: opts.headers || {}
      }, (res) => {
        const chunks = [];
        res.on('data', c => chunks.push(c));
        res.on('end', () => {
          const buf = Buffer.concat(chunks);
          const textStr = buf.toString('utf8');
          resolve({
            ok: res.statusCode >= 200 && res.statusCode < 300,
            status: res.statusCode,
            text: async () => textStr,
            json: async () => JSON.parse(textStr || '{}'),
            arrayBuffer: async () => buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength)
          });
        });
      });
      req.on('error', reject);
      const t = setTimeout(() => { req.destroy(new Error('timeout')); }, Number(opts.timeoutMs || 12000));
      req.on('close', () => clearTimeout(t));
      if (opts.body) req.write(typeof opts.body === 'string' || Buffer.isBuffer(opts.body) ? opts.body : String(opts.body));
      req.end();
    });
  } catch (e) {
    return {
      ok: false,
      status: 0,
      error: 'n8n_sandbox_http_delegated',
      text: async () => '{}',
      json: async () => ({ ok: false, description: 'n8n_sandbox_http_delegated' }),
      arrayBuffer: async () => Buffer.alloc(0)
    };
  }
}
