    WORKSHOP_MEM: $env.WORKSHOP_MEMBER_PRICE || r.memberPrice || '4,000',
    WORKSHOP_NON: $env.WORKSHOP_NONMEMBER_PRICE || r.nonMemberPrice || '6,000',
    PRIVATE_USD: $env.PRIVATE_SESSION_USD || r.privateUsd || '100',
    GROQ_KEY: $env.GROQ_API_KEY || r.groqKey || '',
    OPENAI_KEY: $env.OPENAI_API_KEY || r.openaiKey || '',
    GEMINI_KEY: $env.GEMINI_API_KEY || r.geminiKey || '',
    TG_CEO_TOK: $env.TELEGRAM_CEO_BOT_TOKEN || r.tgCeoToken || '',
    TG_TRADER_TOK: $env.TELEGRAM_TRADER_BOT_TOKEN || r.tgTraderToken || '',
    DISCORD_TOK: $env.DISCORD_BOT_TOKEN || r.discordToken || '',
    ELEVEN_KEY: $env.ELEVENLABS_API_KEY || r.elevenKey || '',
    ELEVEN_VOICE: $env.ELEVENLABS_VOICE_ID || r.elevenVoice || 'pFZP5JQG7iQjIQuC4Bku',
    BRIDGE_SECRET: $env.TRADESAJON_BRIDGE_SECRET || '',
    N8N_INTERNAL: String($env.N8N_INTERNAL_URL || $env.WEBHOOK_URL || 'http://n8n:5678').trim().replace(/\/+$/, '')
  };
}

function escHtml(s) {
  return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

async function withMongo(fn) {
  if (!$env.MONGODB_URI) return await fn(null);
  let client = null;
  try {
    const { MongoClient } = require('mongodb');
    client = new MongoClient($env.MONGODB_URI, { serverSelectionTimeoutMS: 3500, connectTimeoutMS: 5000 });
    await client.connect();
    const db = client.db($env.MONGODB_DB || 'tradesejon_prod');
    return await fn(db);
  } catch (e) {
    return await fn(null);
  } finally {
    if (client) { try { await client.close(); } catch (_) {} }
  }
}

async function fetchLiveMarketPrices() {
  let btc = '$78,250.00', gold = '$3,940.50';
  try {
    const b = await safeFetch('https://api.binance.com/api/v3/ticker/price?symbol=BTCUSDT', { signal: AbortSignal.timeout(2500) }).then(r => r.json());
    if (b && b.price) btc = '$' + Number(b.price).toLocaleString('en-US', { maximumFractionDigits: 2 });
  } catch (_) {}
  try {
    const g = await safeFetch('https://data-asg.goldprice.org/dbXRates/USD', { signal: AbortSignal.timeout(2500) }).then(r => r.json());
    if (g && g.items?.[0]?.xauPrice) gold = '$' + Number(g.items[0].xauPrice).toLocaleString('en-US', { maximumFractionDigits: 2 });
  } catch (_) {}
  return `Gold (XAU/USD): ${gold} | Bitcoin (BTC/USDT): ${btc}`;
}

async function tgApi(tok, method, payload) {
  if (!tok) return { ok: false, description: 'Bot token not configured' };
  try {
    const r = await safeFetch(`https://api.telegram.org/bot${tok}/${method}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload || {})
    });
    return await r.json();
  } catch (e) {
    return { ok: false, description: e.message };
  }
}

async function collectSubscriberChatIds(db) {
  const cids = new Set();
  const unsub = new Set(['999000111']);
  const addCid = (v) => {
    if (v === undefined || v === null) return;
    const s = String(v).trim();
    if (/^[1-9]\d{4,15}$/.test(s) && !unsub.has(s)) cids.add(s);
  };
  if (Array.isArray(_RCTX?.subscriberChatIds)) {
    for (const id of _RCTX.subscriberChatIds) addCid(id);
  }
  if (db) {
    try {
      const [uLeads, v2, tl, ct, cv, tm] = await Promise.all([
        db.collection('leads').find({ status: 'unsubscribed' }).toArray().catch(() => []),
        db.collection('leads').find({ 'telegram.chatId': { $exists: true, $ne: null } }).toArray().catch(() => []),
        db.collection('trading_leads').find({}).limit(200).toArray().catch(() => []),
        db.collection('contacts').find({}).limit(200).toArray().catch(() => []),
        db.collection('conversations').find({ platform: 'telegram_trading' }).limit(200).toArray().catch(() => []),
        db.collection('telegram_messages').find({ bot_type: 'trading' }).limit(200).toArray().catch(() => [])
      ]);
      for (const u of uLeads) if (u.telegram?.chatId) unsub.add(String(u.telegram.chatId));
      for (const d of v2) addCid(d.telegram?.chatId);
      for (const d of tl) { addCid(d.telegram?.chatId); addCid(d.chatId); }
      for (const d of ct) { addCid(d.telegram?.chatId); addCid(d.chatId); }
      for (const d of cv) { addCid(d.chat_id); addCid(d.chatId); addCid(d.user_id); }
      for (const d of tm) { addCid(d.chat_id); addCid(d.chatId); }
    } catch (_) {}
  }
  const envCeo = String($env.CEO_USER_IDS || '').split(/[,;\s]+/).map(s => s.trim()).filter(s => /^[1-9]\d{4,15}$/.test(s));
  for (const id of envCeo) addCid(id);
  return Array.from(cids);
}

async function resolveProfile(db, target) {
  const q = String(target || '').trim();
  if (!q || !db) return null;
  const rx = new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
  for (const col of ['contacts', 'trading_leads', 'leads', 'members']) {
    const doc = await db.collection(col).findOne({
      $or: [{ email: q.toLowerCase() }, { phone: q }, { full_name: rx }, { name: rx }, { telegram_username: rx }]
    }).catch(() => null);
    if (doc) return doc;
  }
  return null;
}

async function sendSmtpEmail(toEmail, subject, htmlBody) {
  const { BRAND } = cfg();
  const smtpUser = $env.SMTP_USER || $env.GMAIL_USER || '';
  const smtpPass = $env.SMTP_PASSWORD || $env.GMAIL_APP_PASSWORD || '';
  if (!smtpUser || !smtpPass) return { ok: false, error: 'SMTP credentials not configured in .env' };
  try {
    const nodemailer = require('nodemailer');
    const transporter = nodemailer.createTransport({
      host: $env.SMTP_HOST || 'smtp.gmail.com',
      port: Number($env.SMTP_PORT || 465),
      secure: true,
      auth: { user: smtpUser, pass: smtpPass }
    });
    const info = await transporter.sendMail({ from: `${BRAND} AIOS <${smtpUser}>`, to: toEmail, subject, html: htmlBody });
    return { ok: true, to: toEmail, messageId: info.messageId };
  } catch (e) {
    return { ok: false, error: e.message };
  }
}

function matchFaq(text) {
  const { BRAND, PLATFORMS, SCHEDULE, MENTORS, VIP_USD, WORKSHOP_MEM, WORKSHOP_NON, PRIVATE_USD } = cfg();
  const FAQS = [
    { keys: ['مبتدئ', 'ابدأ', 'الفيديوهات', 'video', 'start', 'begin'], a: `في ${BRAND} بنبدأ معاك من الصفر بخطة تدريبية منظمة وتطبيق لايف لتتقن استراتيجية Hyper-Scalping خطوة بخطوة.` },
    { keys: ['متطلبات', 'احتاج', 'محتاج', 'requirements'], a: 'لابتوب أو كمبيوتر، إنترنت مستقر، والتفرغ لحضور الجلسات اللايف المباشرة.' },
    { keys: ['راس المال', 'رأس المال', 'capital', 'budget', 'مبلغ'], a: 'تقدر تبدأ بمرونة من $100 إلى $500 مع إدارة صارمة لرأس المال (WIN BIG, win small, lose small).' },
    { keys: ['منصة', 'منصات', 'شركات', 'brokers', 'platforms', 'webull', 'ibkr'], a: `ندعم رسمياً منصات: ${PLATFORMS}.` },
    { keys: ['موعد', 'مواعيد', 'توقيت', 'الساعة كام', 'schedule', 'session time'], a: `أوقات الجلسات المباشرة اليومية: ${SCHEDULE}.` },
    { keys: ['منتور', 'المنتورز', 'مدربين', 'mentors', 'coaches', 'مين'], a: `فريق التوجيه المعتمد في ${BRAND}: ${MENTORS}.` },
    { keys: ['سعر', 'اسعار', 'أسعار', 'اشتراك', 'pricing', 'vip', 'workshop', 'ورشة'], a: `• اشتراك Discord VIP & Scanner: $${VIP_USD}/شهرياً.\n• الورشة الأوفلاين: ${WORKSHOP_MEM} للمشتركين / ${WORKSHOP_NON} لغير المشتركين.\n• الجلسة الخاصة 1-on-1 (4 ساعات): $${PRIVATE_USD}.` }
  ];
  const low = String(text || '').toLowerCase();
  if (/(?:خلي|عدل|غير|change|set|update|notify|بلغ|ابعت|أبعت|احذف|delete|add|اضف|أضف|search|ابحث|اعتمد|approve)/i.test(low)) return null;
  const isMarketQuery = /(?:دهب|ذهب|بيتكوين|يورو|ناسداك|gold|btc|bitcoin|xau|eurusd|us100|eth)/i.test(low);
  for (const f of FAQS) {
    if (isMarketQuery && f.keys.includes('سعر')) continue;
    let hits = 0;
    for (const k of f.keys) if (low.includes(k)) hits++;
    if (hits >= 1 && low.length < 140) return `💡 <b>${escHtml(BRAND)} Knowledge Base:</b>\n\n${escHtml(f.a)}`;
  }
  return null;
}

async function planWithLlm(userPrompt, contextSummary, history = []) {
  const { BRAND, MENTORS, PLATFORMS, VIP_USD, SCHEDULE, GROQ_KEY, OPENAI_KEY, GEMINI_KEY } = cfg();
  const sys = `# EXECUTIVE AGENT — ${BRAND} AIOS (n8n-Native)
You are the Unified CEO Agentic AI Brain running inside n8n workflows, synced 100% with AIOS Web Chat, Telegram, Discord, MongoDB CRM, and RAG Knowledge Base.
Respond in the user's language (natural Egyptian Arabic, Franco-Arabic, or English).
NEVER fabricate delivery confirmations, emails, DMs, or statistics.
Mentors: ${MENTORS} | Platforms: ${PLATFORMS} | VIP: $${VIP_USD}/mo | Schedule: ${SCHEDULE}.

Available tools (return MULTIPLE actions inside "actions" in execution order for compound requests):
1. search_system | {"query": "...", "scope": "all|crm|knowledge|tickets"}
2. add_knowledge | {"title": "...", "content": "...", "category": "general|pricing|faq|policies"}
3. delete_knowledge | {"slug_or_query": "..."}
4. list_knowledge | {}
5. add_crm_lead | {"name": "...", "email": "...", "phone": "...", "tier": "prospect|vip_recurring"}
6. delete_crm_contact | {"target": "email or phone or exact name"}
7. approve_lead | {"target": "latest | email | phone | name", "plan": "..."}
8. get_system_kpis | {}
9. get_market_prices | {}
10. update_campaign_settings | {"session_time": "...", "zoom_url": "...", "whop_url": "..."}
11. send_email | {"target": "...", "content": "..."}
12. send_discord_dm | {"target": "...", "message": "..."}
13. send_telegram_dm | {"target": "t.me link, chat_id, @username, phone, email, or name", "message": "..."} (SINGLE user only, NEVER broadcast)
14. broadcast_telegram | {"message": "..."} (ONLY when user explicitly asks to notify all subscribers/traders/everyone)
15. trigger_workflow | {"workflow_path": "tradesejon-...", "payload": {}}
16. direct_answer | {}

Live Context:
${contextSummary}

Return valid JSON only:
{"thought": "...", "actions": [{"tool": "...", "args": {}}], "reply_html": "..."}`;

  const msgHistory = Array.isArray(history)
    ? history.slice(-6).filter(m => m && m.role && m.content).map(m => ({ role: m.role, content: String(m.content).slice(0, 600) }))
    : [];

  if (GROQ_KEY) {
    for (const model of ['openai/gpt-oss-120b', 'qwen/qwen3.8-27b', 'openai/gpt-oss-20b', 'llama-3.3-70b-versatile']) {
      try {
        const res = await safeFetch('https://api.groq.com/openai/v1/chat/completions', {
          method: 'POST',
          headers: { 'Authorization': `Bearer ${GROQ_KEY}`, 'Content-Type': 'application/json' },
          body: JSON.stringify({
            model,
            messages: [{ role: 'system', content: sys }, ...msgHistory, { role: 'user', content: userPrompt }],
            response_format: { type: 'json_object' },
            temperature: 0.2,
            max_tokens: 2000
          })
        });
        const j = await res.json();
        let raw = j.choices?.[0]?.message?.content;
        if (raw) {
          raw = raw.replace(/<think>[\s\S]*?<\/think>/g, '').replace(/^```json|```$/gm, '').trim();
          const parsed = JSON.parse(raw);
          if (parsed && Array.isArray(parsed.actions)) return parsed;
        }
      } catch (_) {}
    }
  }

  if (OPENAI_KEY) {
    try {
      const res = await safeFetch('https://api.openai.com/v1/chat/completions', {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${OPENAI_KEY}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: 'gpt-4o-mini',
          messages: [{ role: 'system', content: sys }, ...msgHistory, { role: 'user', content: userPrompt }],
          response_format: { type: 'json_object' },
          temperature: 0.2
        })
      });
      const j = await res.json();
      let raw = j.choices?.[0]?.message?.content;
      if (raw) {
        const parsed = JSON.parse(raw.replace(/^```json|```$/gm, '').trim());
        if (parsed && Array.isArray(parsed.actions)) return parsed;
      }
    } catch (_) {}
  }

  if (GEMINI_KEY) {
    try {
      const res = await safeFetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${GEMINI_KEY}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          contents: [{ parts: [{ text: `${sys}\n\nUser request:\n${userPrompt}` }] }],
          generationConfig: { responseMimeType: 'application/json', temperature: 0.2, maxOutputTokens: 1500 }
        })
      });
      const j = await res.json();
      let raw = j.candidates?.[0]?.content?.parts?.[0]?.text;
      if (raw) {
        const parsed = JSON.parse(raw.replace(/^```json|```$/gm, '').trim());
        if (parsed && Array.isArray(parsed.actions)) return parsed;
      }
    } catch (_) {}
  }

  return null;
}

async function runTool(db, act, ctx) {
  const tool = String(act?.tool || 'direct_answer');
  const args = act?.args || {};
  const { BRAND, BRIDGE_SECRET, N8N_INTERNAL, TG_TRADER_TOK, TG_CEO_TOK, DISCORD_TOK } = cfg();
  const rctx = _RCTX || {};

  if (tool === 'get_market_prices') {
    return { tool, ok: true, livePrices: ctx.livePrices };
  }

  if (tool === 'get_system_kpis') {
    return { tool, ok: true, ...(ctx.stats || {}), livePrices: ctx.livePrices };
  }

  if (tool === 'trigger_workflow') {
    const wfPath = String(args.workflow_path || '').replace(/^\/+/, '');
    if (!wfPath) return { tool, ok: false, error: 'Missing workflow_path' };
    try {
      const hdrs = { 'Content-Type': 'application/json' };
      if (BRIDGE_SECRET) hdrs['x-tradesejon-secret'] = BRIDGE_SECRET;
      const r = await safeFetch(`${N8N_INTERNAL}/webhook/${wfPath}`, {
        method: 'POST',
        headers: hdrs,
        body: JSON.stringify(args.payload || {})
      });
      return { tool, ok: r.ok, workflow: wfPath, status: r.status };
    } catch (e) {
      return { tool, ok: false, workflow: wfPath, error: e.message };
    }
  }

  if (tool === 'search_system') {
    const q = String(args.query || ctx.prompt || '').trim();
    const scope = String(args.scope || 'all').toLowerCase();
    const out = { tool, ok: true, crm: [], tickets: [], knowledge: [] };
    const rx = new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
    if (db) {
      if (scope === 'all' || scope === 'crm') {
        const leads = await db.collection('trading_leads').find({ $or: [{ full_name: rx }, { email: rx }, { phone: rx }] }).limit(5).toArray().catch(() => []);
        const contacts = await db.collection('contacts').find({ $or: [{ full_name: rx }, { name: rx }, { email: rx }, { phone: rx }] }).limit(5).toArray().catch(() => []);
        out.crm = [...leads, ...contacts].map(d => ({ name: d.full_name || d.name || 'Lead', email: d.email || '', phone: d.phone || '', status: d.status || '' }));
      }
      if (scope === 'all' || scope === 'knowledge') {
        const kb = await db.collection('kb_articles').find({ $or: [{ title: rx }, { content: rx }] }).limit(5).toArray().catch(() => []);
        out.knowledge = kb.map(k => ({ title: k.title, snippet: String(k.content || '').slice(0, 180) }));
      }
    }
    if (out.knowledge.length === 0 && (scope === 'all' || scope === 'knowledge') && Array.isArray(rctx.kbItems)) {
      out.knowledge = rctx.kbItems.filter(k => rx.test(`${k.title || ''} ${k.content || ''}`)).slice(0, 5)
        .map(k => ({ title: k.title, snippet: String(k.content || '').slice(0, 180) }));
    }
    return out;
  }

  if (tool === 'list_knowledge') {
    let items = db ? await db.collection('kb_articles').find({}).sort({ updated_at: -1 }).limit(20).toArray().catch(() => []) : [];
    if ((!items || items.length === 0) && Array.isArray(rctx.kbItems)) {
      items = rctx.kbItems;
    }
    return { tool, ok: true, count: items.length, items: items.map(i => ({ title: i.title, slug: i.slug })) };
  }

  if (tool === 'add_knowledge') {
    const title = String(args.title || 'Synced Rule').trim();
    const content = String(args.content || '').trim();
    const category = String(args.category || 'general');
    if (!content) return { tool, ok: false, error: 'Missing knowledge content' };
    const slug = (title.toLowerCase().replace(/[^a-z0-9\u0600-\u06FF]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 48) || 'rule') + '_' + Date.now().toString(36).slice(-4);
    if (db) {
      await db.collection('kb_articles').updateOne({ slug }, { $set: { slug, title, category, content, updated_at: new Date() } }, { upsert: true }).catch(() => {});
      await db.collection('knowledge_chunks').insertOne({ slug, title, chunk_index: 0, text: content.slice(0, 2000), updated_at: new Date() }).catch(() => {});
      await db.collection('aios_super_memory').insertOne({ type: 'n8n_knowledge_ingest', slug, title, rule: content, updated_at: new Date() }).catch(() => {});
    }
    return { tool, ok: true, title, slug, content, category, chunks: 1 };
  }

  if (tool === 'delete_knowledge') {
    const q = String(args.slug_or_query || '').trim();
    if (!q || q === '*' || q.toLowerCase() === 'all') return { tool, ok: false, error: 'Wildcard deletion blocked by safety guard.' };
    const rx = new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
    let doc = db ? await db.collection('kb_articles').findOne({ $or: [{ slug: q }, { title: rx }] }).catch(() => null) : null;
    if (!doc && Array.isArray(rctx.kbItems)) {
      doc = rctx.kbItems.find(i => i.slug === q || rx.test(i.title || '')) || null;
    }
    if (!doc) return { tool, ok: false, error: `No knowledge entry matched "${q}".` };
    if (db) {
      await db.collection('kb_articles').deleteOne({ slug: doc.slug }).catch(() => {});
      await db.collection('knowledge_chunks').deleteMany({ slug: doc.slug }).catch(() => {});
    }
    return { tool, ok: true, deleted_title: doc.title, deleted_slug: doc.slug };
  }

  if (tool === 'add_crm_lead') {
    const name = String(args.name || 'New Lead').trim();
    const email = String(args.email || '').trim().toLowerCase();
    const phone = String(args.phone || '').trim();
    const status = String(args.status || 'prospect');
    if (!email && !phone) return { tool, ok: false, error: 'Provide an email or phone number to save lead.' };
    if (db) {
      const f = email ? { email } : { phone };
      const doc = { name, full_name: name, email: email || undefined, phone: phone || undefined, status, updatedAt: new Date() };
      await db.collection('trading_leads').updateOne(f, { $set: doc, $setOnInsert: { createdAt: new Date() } }, { upsert: true }).catch(() => {});
      await db.collection('contacts').updateOne(f, { $set: doc, $setOnInsert: { createdAt: new Date() } }, { upsert: true }).catch(() => {});
    }
    return { tool, ok: true, name, email, phone, status };
  }

  if (tool === 'delete_crm_contact') {
    const target = String(args.target || '').trim();
    if (!target || target === '*' || target.toLowerCase() === 'all') return { tool, ok: false, error: 'Wildcard deletion blocked by safety guard.' };
    let deleted = 0;
    if (db) {
      const rx = new RegExp(`^${target.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}$`, 'i');
      const f = { $or: [{ email: target.toLowerCase() }, { phone: target }, { full_name: rx }, { name: rx }] };
      const [r1, r2, r3] = await Promise.all([
        db.collection('trading_leads').deleteOne(f).catch(() => ({ deletedCount: 0 })),
        db.collection('contacts').deleteOne(f).catch(() => ({ deletedCount: 0 })),
        db.collection('leads').deleteOne(f).catch(() => ({ deletedCount: 0 }))
      ]);
      deleted = (r1.deletedCount || 0) + (r2.deletedCount || 0) + (r3.deletedCount || 0);
      if (deleted) await db.collection('audit_logs').insertOne({ action: 'n8n_delete_crm', target, deleted, at: new Date() }).catch(() => {});
    }
    return { tool, ok: Boolean(deleted || !db), target, deleted_records: deleted, delegated_sync: !db };
  }

  if (tool === 'approve_lead') {
    const target = String(args.target || 'latest').trim();
    if (!db) return { tool, ok: false, error: 'MongoDB not connected in n8n .env' };
    let lead = null;
    if (/^(?:latest|last|newest|recent|آخر|اخر|أحدث|احدث)$/i.test(target)) {
      const arr = await db.collection('trading_leads').find({}).sort({ createdAt: -1, _id: -1 }).limit(1).toArray().catch(() => []);
      lead = arr[0] || (await db.collection('leads').find({}).sort({ createdAt: -1, _id: -1 }).limit(1).toArray().catch(() => []))[0] || null;
    } else {
      lead = await resolveProfile(db, target);
    }
    if (!lead) return { tool, ok: false, error: `No lead matched "${target}".` };
    const name = lead.full_name || lead.name || 'Trader';
    const email = String(lead.email || '').trim().toLowerCase();
    const updF = lead._id ? { _id: lead._id } : (email ? { email } : { full_name: name });
    await Promise.all([
      db.collection('trading_leads').updateOne(updF, { $set: { status: 'approved', approvedAt: new Date() } }).catch(() => {}),
      db.collection('leads').updateOne(email ? { email } : updF, { $set: { status: 'approved', approvedAt: new Date() } }).catch(() => {}),
      db.collection('contacts').updateOne(email ? { email } : updF, { $set: { status: 'approved', approvedAt: new Date() } }).catch(() => {})
    ]);
    let emailSent = false, messageId = '', errMsg = '';
    if (email) {
      const mr = await sendSmtpEmail(email, `${BRAND} VIP Access Approved`, `<p>Welcome ${escHtml(name)}, your ${escHtml(BRAND)} VIP application has been approved.</p>`);
      emailSent = Boolean(mr.ok);
      messageId = mr.messageId || '';
      errMsg = mr.error || '';
    }
    return { tool, ok: true, name, email, emailSent, messageId, error: errMsg || undefined };
  }

  if (tool === 'update_campaign_settings') {
    const setObj = { updatedAt: new Date() };
    if (args.session_time) setObj.startAt = String(args.session_time).trim();
    if (args.zoom_url) setObj.zoomMeetingUrl = String(args.zoom_url).trim();
    if (args.whop_url) setObj.whopCheckoutUrl = String(args.whop_url).trim();
    if (db) {
      await db.collection('campaigns').updateOne({ _id: 'workshop-poc' }, { $set: setObj }, { upsert: true }).catch(() => {});
      await db.collection('aios_config').updateOne({ key: 'session_settings' }, { $set: { session_time: setObj.startAt || '', zoom_url: setObj.zoomMeetingUrl || '', updated_at: new Date().toISOString() } }, { upsert: true }).catch(() => {});
    }
    return { tool, ok: true, updated: setObj, session_time: setObj.startAt };
  }

  if (tool === 'send_email') {
    const prof = await resolveProfile(db, args.target || '').catch(() => null);
    const toEmail = prof?.email || (String(args.target || '').includes('@') ? String(args.target).trim().toLowerCase() : '');
    if (!toEmail) return { tool, ok: false, error: `Email not found for "${args.target || ''}".` };
    const mr = await sendSmtpEmail(toEmail, `${BRAND} Executive Update`, `<p>${escHtml(args.content || ctx.prompt)}</p>`);
    if (mr.ok && db) await db.collection('outbound_emails').insertOne({ to: toEmail, subject: `${BRAND} Executive Update`, messageId: mr.messageId, sentAt: new Date(), status: 'sent' }).catch(() => {});
    return { tool, ok: Boolean(mr.ok), to: toEmail, messageId: mr.messageId, error: mr.error };
  }

  if (tool === 'send_discord_dm') {
    if (!DISCORD_TOK) return { tool, ok: false, error: 'DISCORD_BOT_TOKEN not configured in n8n .env' };
    const prof = await resolveProfile(db, args.target || '').catch(() => null);
    const did = /^\d{16,21}$/.test(String(args.target || '').trim()) ? String(args.target).trim() : (prof?.discord_user_id || '');
    if (!did) return { tool, ok: false, error: `Discord User ID not found for "${args.target || ''}".` };
    const ch = await safeFetch('https://discord.com/api/v10/users/@me/channels', {
      method: 'POST', headers: { 'Authorization': `Bot ${DISCORD_TOK}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ recipient_id: did })
    }).then(r => r.json()).catch(() => ({}));
    if (!ch.id) return { tool, ok: false, error: ch.message || 'Discord DM channel rejected' };
    const sent = await safeFetch(`https://discord.com/api/v10/channels/${ch.id}/messages`, {
      method: 'POST', headers: { 'Authorization': `Bot ${DISCORD_TOK}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ content: String(args.message || 'Executive update') })
    }).then(r => r.json()).catch(() => ({}));
    return { tool, ok: Boolean(sent.id), userId: did, messageId: sent.id, error: sent.message };
  }

  if (tool === 'send_telegram_dm') {
    const rawT = String(args.target || '').trim();
    const msg = String(args.message || 'Executive notification').trim();
    const linkM = rawT.match(/https?:\/\/t\.me\/contact\/([0-9]{5,16})/i);
    let cid = linkM ? linkM[1] : (/^\d{5,16}$/.test(rawT) ? rawT : '');
    if (!cid && rawT && db) {
      const prof = await resolveProfile(db, rawT.replace(/^@/, ''));
      cid = prof?.chatId || prof?.telegram?.chatId || '';
    }
    if (!cid) return { tool, ok: false, broadcast_prevented: true, error: `Could not resolve numeric Telegram chat_id for "${rawT}". No broadcast triggered.` };
    const tok = TG_TRADER_TOK || TG_CEO_TOK;
    const res = await tgApi(tok, 'sendMessage', { chat_id: cid, text: escHtml(msg), parse_mode: 'HTML' });
    return { tool, ok: Boolean(res.ok), single_user_only: true, chatId: cid, message: msg, messageId: res.result?.message_id, error: res.description };
  }

  if (tool === 'broadcast_telegram') {
    const msg = String(args.message || '').trim();
    if (!msg) return { tool, ok: false, error: 'Missing broadcast message' };
    const tok = TG_TRADER_TOK || TG_CEO_TOK;
    if (!tok) return { tool, ok: false, error: 'TELEGRAM_TRADER_BOT_TOKEN not configured' };
    const cids = await collectSubscriberChatIds(db);
    let sent = 0, failed = 0, lastErr = '';
    for (const cid of cids) {
      const r = await tgApi(tok, 'sendMessage', { chat_id: cid, text: escHtml(msg), parse_mode: 'HTML' });
      if (r && r.ok) sent++; else { failed++; if (r && r.description) lastErr = r.description; }
    }
    return { tool, ok: sent > 0, sent, failed, total: cids.length, message: msg, error: sent === 0 ? (lastErr || 'Delivery failed') : undefined };
  }

  return { tool: 'direct_answer', ok: true };
}

async function runAgenticBrain(userPrompt, { channel = 'aios_n8n', history = [], wantVoice = false, tgReplyChatId = '', tgReplyTok = '', runtimeCtx = null } = {}) {
  _RCTX = runtimeCtx && typeof runtimeCtx === 'object' ? runtimeCtx : {};
  const { BRAND, SCHEDULE, ELEVEN_KEY, ELEVEN_VOICE } = cfg();
  const prompt = String(userPrompt || '').trim();
  let livePrices = await fetchLiveMarketPrices();
  if (_RCTX.livePrices && livePrices === 'Gold (XAU/USD): $3,940.50 | Bitcoin (BTC/USDT): $78,250.00') {
    livePrices = String(_RCTX.livePrices);
  }

  const faqAns = matchFaq(prompt);
  if (faqAns) {
    if (tgReplyChatId && tgReplyTok) await tgApi(tgReplyTok, 'sendMessage', { chat_id: tgReplyChatId, text: faqAns, parse_mode: 'HTML' });
    return { ok: true, engine: 'n8n_agentic_brain', thought: 'Matched official Knowledge Base', actions: [{ tool: 'faq_knowledge_query', ok: true }], reply: faqAns, voice_enabled: false, audioBase64: null };
  }

  const tgLinkM = prompt.match(/https?:\/\/t\.me\/contact\/([0-9]{5,16})(?::[^\s]+)?/i);
  if (tgLinkM && !/(?:everyone|all subscribers|للكل|لكل المتداولين)/i.test(prompt)) {
    const targetCid = tgLinkM[1];
    const afterLink = prompt.slice(tgLinkM.index + tgLinkM[0].length)
      .replace(/^(?:2ollo|2olo|2olha|قوله|قولها|بلغه|en|inn|that|saying|msg|message|:|-|\s)+/i, '').trim() || 'Executive notification';
    const r = await runTool(null, { tool: 'send_telegram_dm', args: { target: targetCid, message: afterLink } }, { prompt, livePrices });
    const rep = r.ok
      ? `✅ <b>Verified Delivered to Single Telegram User Only (No Broadcast)!</b>\n🆔 Chat ID: <code>${escHtml(targetCid)}</code>\n📝 Message: "${escHtml(afterLink)}"`
      : `⚠️ Telegram delivery rejected for Chat ID <code>${escHtml(targetCid)}</code>: ${escHtml(r.error || 'Forbidden')}. No broadcast was sent.`;
    if (tgReplyChatId && tgReplyTok) await tgApi(tgReplyTok, 'sendMessage', { chat_id: tgReplyChatId, text: rep, parse_mode: 'HTML' });
    return { ok: r.ok, engine: 'n8n_agentic_brain', thought: 'Targeted single-user Telegram DM firewall', actions: [r], reply: rep, voice_enabled: false, audioBase64: null };
  }

  return await withMongo(async (db) => {
    const sessM = prompt.match(/(?:جلسة|جلسه|سيشن|session)\s*(?:النهاردة|اليوم|today)?\s*(?:الساعة|الساعه|sa3a|at)?\s*([0-9]{1,2}(?::[0-9]{2})?|٧(?::٣٠)?|٩(?::٣٠)?)/i);
    if (sessM) {
      const tm = sessM[1];
      const norm = tm.includes('PM') || tm.includes('AM') ? `${tm} (بتوقيت القاهرة)` : `${tm} PM (بتوقيت القاهرة)`;
      const upd = await runTool(db, { tool: 'update_campaign_settings', args: { session_time: norm } }, { prompt, livePrices });
      const acts = [upd];
      let rep = `✅ تمام يا فندم! تم تعديل موعد جلسة التداول المباشرة رسمياً إلى <b>${escHtml(norm)}</b> عبر n8n Agentic AI ومزامنتها فوراً 🎯`;
      if (/(?:بلغ|بلّغ|نبه|نبّه|اعلن|أعلن|notify|announce)/i.test(prompt) && /(?:مشترك|الكل|الاعضاء|الأعضاء|المتداولين|subscribers|members|everyone)/i.test(prompt)) {
        const bRes = await runTool(db, { tool: 'broadcast_telegram', args: { message: `📢 <b>تحديث موعد الجلسة المباشرة</b>\nجلسة التداول النهاردة الساعة <b>${norm}</b>.\nنشوفكم على الجلسة! 🚀` } }, { prompt, livePrices });
        acts.push(bRes);
        rep += `\n\n📣 <b>تم إبلاغ المشتركين:</b> ${bRes.sent || 0} وصلت` + (bRes.failed ? ` | ${bRes.failed} فشلت` : '.');
      }
      if (tgReplyChatId && tgReplyTok) await tgApi(tgReplyTok, 'sendMessage', { chat_id: tgReplyChatId, text: rep, parse_mode: 'HTML' });
      return { ok: true, engine: 'n8n_agentic_brain', thought: 'Executed session update (+ optional broadcast) via n8n', actions: acts, actionsExecuted: acts, reply: rep, voice_enabled: false, audioBase64: null };
    }

    const rStats = _RCTX?.stats || {};
    const [campDoc, dbContacts, dbLeads, dbTrading, dbEmails, dbKb] = db ? await Promise.all([
      db.collection('campaigns').findOne({ _id: 'workshop-poc' }).catch(() => null),
      db.collection('contacts').countDocuments().catch(() => 0),
      db.collection('leads').countDocuments().catch(() => 0),
      db.collection('trading_leads').countDocuments().catch(() => 0),
      db.collection('outbound_emails').countDocuments().catch(() => 0),
      db.collection('kb_articles').find({}).sort({ updated_at: -1 }).limit(10).toArray().catch(() => [])
    ]) : [null, 0, 0, 0, 0, []];

    const stats = {
      nContacts: dbContacts || Number(rStats.nContacts || 0),
      nLeadsV2: dbLeads || Number(rStats.nLeadsV2 || 0),
      nTradingLeads: dbTrading || Number(rStats.nTradingLeads || 0),
      nOutboundEmails: dbEmails || Number(rStats.nOutboundEmails || 0)
    };
    const kbList = (dbKb && dbKb.length) ? dbKb : (Array.isArray(_RCTX?.kbItems) ? _RCTX.kbItems : []);
    const kbTxt = kbList.length ? '\nKB Entries: ' + kbList.map(k => k.title).join(', ') : '';
    const ctxSum = `Channel: ${channel}\nLive Prices: ${livePrices}\nSession: ${campDoc?.startAt || SCHEDULE}\nCRM Stats: contacts=${stats.nContacts}, leads=${stats.nLeadsV2}, trading_leads=${stats.nTradingLeads}, emails=${stats.nOutboundEmails}${kbTxt}`;

    let plan = await planWithLlm(prompt, ctxSum, history);
    if (!plan && _RCTX && _RCTX.preplanned && Array.isArray(_RCTX.preplanned.actions)) {
      plan = _RCTX.preplanned;
    }
    if (!plan) {
      const low = prompt.toLowerCase();
      if (/^(?:approve|accept|اعتمد|اقبل|موافقة)(?=\s|$|[:.,!؟?])/i.test(low)) {
        plan = { thought: 'Fallback approve lead', actions: [{ tool: 'approve_lead', args: { target: 'latest' } }], reply_html: '' };
      } else if (/^(?:add|save|اضف|أضف|احفظ)\s+(?:a\s+|new\s+)?(?:kb|knowledge|rule|doc|معلومة|قاعدة)(?=\s|$|[:.,!؟?])/i.test(low)) {
        const rawRule = prompt.replace(/^(?:add|save|اضف|أضف|احفظ)\s+(?:a\s+|new\s+)?(?:kb|knowledge|rule|doc|معلومة|قاعدة)(?:\s*(?:جديدة|جديد))?\s*:?\s*/i, '').trim();
        const parts = rawRule.split('|');
        plan = { thought: 'Fallback KB add', actions: [{ tool: 'add_knowledge', args: { title: (parts[0] || '').trim(), content: (parts.length > 1 ? parts.slice(1).join('|') : rawRule).trim(), category: 'general' } }], reply_html: '' };
      } else if (/^(?:delete|remove|امسح|احذف)\s+(?:kb|knowledge|rule|doc|معلومة|قاعدة)(?=\s|$|[:.,!؟?])/i.test(low)) {
        const target = prompt.replace(/^(?:delete|remove|امسح|احذف)\s+(?:kb|knowledge|rule|doc|معلومة|قاعدة)\s*/i, '').trim();
        plan = { thought: 'Fallback KB delete', actions: [{ tool: 'delete_knowledge', args: { slug_or_query: target } }], reply_html: '' };
      } else if (/(?:list\s+(?:all\s+)?(?:kb|knowledge|articles)|قائمة\s+المعرفة|اعرض\s+المعرفة)/i.test(low)) {
        plan = { thought: 'Fallback list KB', actions: [{ tool: 'list_knowledge', args: {} }], reply_html: '' };
      } else if (/(?:\b(?:kpis?|stats|metrics)\b|احصائيات|إحصائيات|حالة\s+السيستم)/i.test(low)) {
        plan = { thought: 'Fallback KPIs', actions: [{ tool: 'get_system_kpis', args: {} }], reply_html: '' };
      } else if (/(?:price|prices|gold|btc|الدهب|الذهب|البيتكوين|سعر)/i.test(low)) {
        plan = { thought: 'Fallback market prices', actions: [{ tool: 'get_market_prices', args: {} }], reply_html: '' };
      } else {
        plan = { thought: 'Fallback status summary', actions: [{ tool: 'direct_answer', args: {} }], reply_html: `🤖 <b>${escHtml(BRAND)} n8n Autonomous Agent</b>\n• Live Prices: ${escHtml(livePrices)}\n• CRM: Contacts=${stats.nContacts}, Leads=${stats.nTradingLeads}, Emails=${stats.nOutboundEmails}` };
      }
    }

    const actions = [];
    const lines = [];
    for (const a of (plan.actions || [])) {
      if (!a || !a.tool || a.tool === 'direct_answer') { actions.push({ tool: 'direct_answer', ok: true }); continue; }
      const r = await runTool(db, a, { prompt, livePrices, stats });
      actions.push(r);
      if (!r.ok) lines.push(`⚠️ <b>${escHtml(r.tool)}:</b> ${escHtml(r.error || 'Failed')}`);
      else if (r.tool === 'get_system_kpis') lines.push(`📊 <b>Live KPIs:</b> Contacts=${r.nContacts}, Leads=${r.nLeadsV2}, TradingLeads=${r.nTradingLeads}, Emails=${r.nOutboundEmails}`);
      else if (r.tool === 'get_market_prices') lines.push(`📈 <b>Live Market Prices:</b> ${escHtml(r.livePrices)}`);
      else if (r.tool === 'list_knowledge') lines.push(`📚 <b>Knowledge Base (${r.count}):</b> ` + (r.items || []).map(i => escHtml(i.title)).join(', '));
      else if (r.tool === 'add_knowledge') lines.push(`✅ <b>Synced Knowledge:</b> ${escHtml(r.title)}`);
      else if (r.tool === 'delete_knowledge') lines.push(`🗑️ <b>Deleted Knowledge:</b> ${escHtml(r.deleted_title)}`);
      else if (r.tool === 'search_system') lines.push(`🔍 <b>Search Results:</b> CRM=${r.crm.length}, KB=${r.knowledge.length}`);
      else if (r.tool === 'add_crm_lead') lines.push(`✅ <b>Saved Lead:</b> ${escHtml(r.name)}`);
      else if (r.tool === 'delete_crm_contact') lines.push(`🗑️ <b>Deleted CRM Record:</b> ${escHtml(r.target)} (${r.deleted_records})`);
      else if (r.tool === 'approve_lead') lines.push(`✅ <b>Approved Lead:</b> ${escHtml(r.name)}` + (r.emailSent ? ` | Email Sent (${escHtml(r.email)})` : ''));
      else if (r.tool === 'update_campaign_settings') lines.push(`🎯 <b>Campaign Updated:</b> ${escHtml(r.updated?.startAt || 'Saved')}`);
      else if (r.tool === 'broadcast_telegram') lines.push(`📣 <b>Broadcast Sent:</b> ${r.sent}/${r.total} subscribers`);
      else if (r.tool === 'send_telegram_dm') lines.push(`📲 <b>Telegram DM Sent:</b> Chat ID <code>${escHtml(r.chatId)}</code>`);
      else if (r.tool === 'send_discord_dm') lines.push(`💬 <b>Discord DM Sent:</b> User <code>${escHtml(r.userId)}</code>`);
      else if (r.tool === 'send_email') lines.push(`✉️ <b>Email Sent:</b> ${escHtml(r.to)}`);
    }

    const reply = lines.length
      ? lines.join('\n\n') + (plan.reply_html && !actions.some(x => !x.ok) ? `\n\n${plan.reply_html}` : '')
      : (plan.reply_html || '✅ Executed.');

    if (db) {
      await db.collection('aios_super_memory').insertOne({
        channel, prompt, thought: plan.thought, actions, reply, at: new Date()
      }).catch(() => {});
    }

    if (tgReplyChatId && tgReplyTok) {
      await tgApi(tgReplyTok, 'sendMessage', { chat_id: tgReplyChatId, text: reply, parse_mode: 'HTML' });
    }

    let audioBase64 = null;
    if (wantVoice && ELEVEN_KEY) {
      try {
        const plain = reply.replace(/<[^>]+>/g, '').slice(0, 400);
        const ttsRes = await safeFetch(`https://api.elevenlabs.io/v1/text-to-speech/${ELEVEN_VOICE}`, {
          method: 'POST',
          headers: { 'xi-api-key': ELEVEN_KEY, 'Content-Type': 'application/json' },
          body: JSON.stringify({ text: plain, model_id: 'eleven_multilingual_v2' })
        });
        if (ttsRes.ok) audioBase64 = Buffer.from(await ttsRes.arrayBuffer()).toString('base64');
      } catch (_) {}
    }

    return {
      ok: true,
      engine: 'n8n_agentic_brain',
      thought: plan.thought || 'n8n execution completed',
      actions,
      actionsExecuted: actions,
      reply,
      voice_enabled: Boolean(audioBase64),
      audioBase64
    };
  });
}


