const isAuthTg = tgFromId && authCeoIds.includes(tgFromId);
if ((BRIDGE_SECRET || authCeoIds.length > 0) && !isAuthSecret && !isAuthTg) {
  return [{ json: { ok: false, authorized: false, httpStatus: 401, error: 'Unauthorized executive access.' } }];
