  try {
    const gf = await safeFetch(`https://api.telegram.org/bot${TG_CEO_TOK}/getFile?file_id=${voiceFileId}`).then(r => r.json());
    if (gf.ok && gf.result?.file_path) {
      const audioRes = await safeFetch(`https://api.telegram.org/file/bot${TG_CEO_TOK}/${gf.result.file_path}`);
      const fd = new FormData();
      fd.append('file', await audioRes.blob(), 'voice.ogg');
      fd.append('model', 'whisper-large-v3-turbo');
      fd.append('language', 'ar');
      const stt = await safeFetch('https://api.groq.com/openai/v1/audio/transcriptions', {
        method: 'POST', headers: { 'Authorization': `Bearer ${GROQ_KEY}` }, body: fd
      }).then(r => r.json());
      if (stt.text) text = stt.text.trim();
    }
  } catch (_) {}
}

