function forceFormatEmail(raw) {
  const cleaned = String(raw || '').replace(/^[\s\u200b-\u200f\u202a-\u202e\ufeff]+|[\s\u200b-\u200f\u202a-\u202e\ufeff]+$/g, '').toLowerCase();
  if (!cleaned || (cleaned.match(/@/g) || []).length !== 1 || cleaned.includes('..') || /\s/.test(cleaned) || !EMAIL_RE.test(cleaned)) return '';
  const domain = cleaned.split('@')[1];
  const tld = domain.split('.').pop();
  if (INVALID_DOMAINS.has(domain) || INVALID_TLDS.has(tld)) return '';
  return cleaned;
}

